export function getSkillCharacter(skillId: string): string | undefined {
    // 内联典故主名（编辑器写入）优先 → 散表
    const entry = getTacticalSkillEntry(skillId);
    if (entry?.ownerName) return entry.ownerName;
    return SKILL_CHARACTER[skillId];
}

